$ErrorActionPreference = "Stop"

$labels = @(
    @{Name="area:minecraft"; Color="0E8A16"; Description="Minecraft integration and mechanics"},
    @{Name="area:agent-runtime"; Color="1D76DB"; Description="Agent lifecycle, identity, and scheduling"},
    @{Name="area:memory"; Color="5319E7"; Description="Persistent memory and consolidation"},
    @{Name="area:learning"; Color="7057FF"; Description="Policies, continual learning, and adaptation"},
