    @{Name="area:multi-agent"; Color="006B75"; Description="Multi-agent interaction and scaling"},
    @{Name="area:training"; Color="B60205"; Description="Training pipelines and model lifecycle"},
    @{Name="area:data"; Color="FBCA04"; Description="Telemetry, datasets, licensing, and privacy"},
    @{Name="area:infra"; Color="C5DEF5"; Description="Developer infrastructure and operations"},
    @{Name="area:docs"; Color="0075CA"; Description="Documentation"},
    @{Name="area:evaluation"; Color="D4C5F9"; Description="Evaluation and benchmarks"},
    @{Name="type:feature"; Color="A2EEEF"; Description="New engineering capability"},
    @{Name="type:research"; Color="BFD4F2"; Description="Decision-oriented research"},
    @{Name="type:experiment"; Color="F9D0C4"; Description="Reproducible experiment"},
    @{Name="type:bug"; Color="D73A4A"; Description="Incorrect behaviour"},
