    @{Name="type:docs"; Color="0E8A16"; Description="Documentation change"},
    @{Name="type:test"; Color="BFDADC"; Description="Test or verification work"},
    @{Name="priority:critical"; Color="B60205"; Description="Blocks the programme or a safety invariant"},
    @{Name="priority:high"; Color="D93F0B"; Description="Important near-term work"},
    @{Name="priority:medium"; Color="FBCA04"; Description="Planned work"},
    @{Name="priority:low"; Color="C2E0C6"; Description="Useful, not time-sensitive"},
    @{Name="status:blocked"; Color="000000"; Description="Cannot proceed until a dependency changes"},
    @{Name="status:needs-design"; Color="FEF2C0"; Description="Needs design or evidence before implementation"},
    @{Name="status:ready"; Color="0E8A16"; Description="Scoped and ready to start"},
    @{Name="good first issue"; Color="7057FF"; Description="Suitable for a new contributor"},
    @{Name="help wanted"; Color="008672"; Description="Maintainers welcome focused help"}
)

$milestones = @(
    "v0.1 — Project Foundation",
    "v0.2 — Minecraft Native Interface",
    "v0.3 — Agent Runtime",
    "v0.4 — Memory",
    "v0.5 — Behaviour Baseline",
    "v0.6 — Language Grounding",
    "v0.7 — Autonomous Behaviour",
    "v0.8 — Lifelong Learning",
    "v0.9 — Multi-Agent Intelligence",
    "v0.10 — Scaling & Simulation",
    "v0.11 — Integrated Research Prototype",
    "v1.0 — Native Intelligence Research Release"
)

function New-IssueSpec($title, $milestone, $labels, $context, $goal, $scope, $deliverables, $acceptance, $dependencies = "None known.", $questions = "") {
    return [ordered]@{Title=$title; Milestone=$milestone; Labels=$labels; Context=$context; Goal=$goal; Scope=$scope; Deliverables=$deliverables; Acceptance=$acceptance; Dependencies=$dependencies; Questions=$questions}
}

