foreach ($label in $labels) {
    gh label create $label.Name --repo $Repository --color $label.Color --description $label.Description --force | Out-Null
}

$existingMilestones = gh api "repos/$Repository/milestones?state=all&per_page=100" | ConvertFrom-Json
foreach ($title in $milestones) {
    if (-not ($existingMilestones | Where-Object title -eq $title)) {
        gh api --method POST "repos/$Repository/milestones" -f title=$title -f description="See ROADMAP.md for outcome, dependencies, and exit gate." | Out-Null
    }
}

$existingIssues = gh issue list --repo $Repository --state all --limit 200 --json title | ConvertFrom-Json
foreach ($issue in $issues) {
    if ($existingIssues | Where-Object title -eq $issue.Title) {
        Write-Host "exists: $($issue.Title)"
        continue
    }

    $researchSection = if ($issue.Questions) { "`n## Research questions`n`n$($issue.Questions)`n" } else { "" }
    $body = @"
## Problem / context

$($issue.Context)

## Goal

$($issue.Goal)

## Scope

$($issue.Scope)
$researchSection
## Likely deliverables

$($issue.Deliverables)

## Acceptance criteria

$($issue.Acceptance)

## Dependencies / blockers

$($issue.Dependencies)
"@
    $labelArgs = @()
    foreach ($labelName in $issue.Labels) { $labelArgs += @("--label", $labelName) }
    gh issue create --repo $Repository --title $issue.Title --body $body --milestone $issue.Milestone @labelArgs | Write-Host
}

Write-Host "Bootstrap complete for ${Repository}: $($labels.Count) labels, $($milestones.Count) milestones, $($issues.Count) issue specifications."
